// 1. استقبال البيانات الخام
const inputJson = $('Webhook').first().json || {};
let data = inputJson.body?.data || inputJson.body || inputJson.data || inputJson;

if (Array.isArray(data)) { data = data[0] || {}; }

// =======================================================
// 1. فلترة الطلبات
// =======================================================
const paymentMethod = (data.payment_method || "").toLowerCase();
const statusSlug = (data.status?.slug || "").toLowerCase();

if (paymentMethod === "free" || paymentMethod.includes("cod") || statusSlug === "waiting" || statusSlug === "awaiting_payment") {
    return [];
}

// =======================================================
// 2. استخراج البيانات
// =======================================================
const orderId = data.reference_id || data.id || "--";
const customerName = data.customer?.full_name || data.customer?.first_name || "عميلنا الغالي";

const mobileCode = (data.customer?.mobile_code || "").replace('+', '');
const mobileNum = (data.customer?.mobile || "").toString();
if (!mobileNum) return [];
const fullMobile = mobileCode + mobileNum;

// =======================================================
// 3. تحليل الطلب وبناء العنوان المجمع
// =======================================================
const allItems = data.items || [];
let coinsParts = [];
let serviceParts = [];
let hasCoins = false;

for (const itm of allItems) {
    const s = (itm.sku || "").toUpperCase();
    const n = (itm.name || "").toLowerCase();

    if (s.includes("COIN") || n.includes("كوينز") || n.includes("coins")) {
        hasCoins = true;

        let coinAmount = "";
        let coinPlatform = "سوني";

        if (n.includes("pc") || n.includes("بي سي")) coinPlatform = "PC";

        for (const o of (itm.options || [])) {
            const val = (typeof o.value === 'object' && o.value.name) ? o.value.name : String(o.value);
            if ((o.name.includes("منصة") || o.name.includes("Platform")) && (val.includes("PC") || val.includes("بي سي"))) {
                coinPlatform = "PC";
            }
            if (o.name.includes("الكمية") || o.name.includes("Amount")) {
                coinAmount = val.trim();
            }
        }

        if (coinAmount) {
            // If amount already contains "كوينز", use it as-is to avoid duplication
            if (coinAmount.includes("كوينز") || coinAmount.toLowerCase().includes("coin")) {
                coinsParts.push(coinAmount);
            } else {
                coinsParts.push(coinAmount + " كوينز " + coinPlatform);
            }
        } else {
            // Fallback: use product name directly
            coinsParts.push(itm.name);
        }
    } else {
        serviceParts.push(itm.name);
    }
}

// بناء العنوان النهائي (كل منتج في سطر)
const allParts = coinsParts.concat(serviceParts);
const finalOrderTitle = allParts.map((item, i) => `${i + 1}. ${item}`).join("\n");

// =======================================================
// 4. صياغة الرسالة
// =======================================================
let statusMsg = "";
let trackingLink = "";
let linkSection = "";
const safetyWarning = "⚠️ *تنبيه هام جداً:*\nلضمان أمان حسابك، يرجى *عدم الدخول للحساب نهائياً* (من اللعبة أو التطبيق) حتى يصلك إشعار الانتهاء.";

// التحقق الفعلي من وجود تحدي (SBC) في الطلبات
let hasSBC = finalOrderTitle.includes("تحدي") || finalOrderTitle.includes("SBC") || finalOrderTitle.includes("sbc");

// نظهر رابط التتبع فقط للكوينز والتحديات
if (hasCoins || hasSBC) {
    trackingLink = "https://track.arab-ut.com/?id=" + orderId;
    linkSection = "\n📝 *لمتابعة الحالة لحظة بلحظة:*\n" + trackingLink;
}

if (hasCoins) {
    statusMsg = "🚀 *حالة الطلب: قيد التنفيذ الآلي* ⚙️\nنظامنا الذكي بدأ في معالجة طلبك حالاً بأعلى معايير الأمان.";
} else {
    statusMsg = "👨‍💻 *حالة الطلب: قيد المراجعة* ⚙️\nتم تحويل طلبك للمختصين لترتيب البدء فيه فوراً.";
}

const finalMsg = "عزيزي العميل/ " + customerName + " 👋\n\nتم استلام طلبك رقم (" + orderId + ") بنجاح ✅\n\n📦 *تفاصيل الطلب:*\n" + finalOrderTitle + "\n\n" + statusMsg + "\n\n" + safetyWarning + "\n" + linkSection + "\n\nشكراً لثقتك في عرب التيمت 🌹";

return {
    mobile: fullMobile,
    messageBody: finalMsg
};

