// Runs ONCE after a coins charge. Freezes poll context.
// No extractable order id => in-band supplier rejection => chargeFailed.
const coins = $('Coins Item').first().json;
let supplier = null, uttOrderId = null, fftOrderId = null;
try {
  const u = $('UTT: Add Order Public').first().json;
  if (u && u.order && u.order.idOrder) { supplier = 'UTT'; uttOrderId = u.order.idOrder; }
} catch (e) {}
if (!supplier) {
  try {
    const f = $('External: Buy Coins').first().json;
    const p = typeof f.data === 'string' ? JSON.parse(f.data) : (f.data || f);
    if (p && p.orderID) { supplier = 'FFT'; fftOrderId = p.orderID; }
  } catch (e) {}
}
const chargeFailed = !supplier;
const isSlow = !!coins.isSlowShipping;
return [{ json: {
  supplier: supplier || 'FFT',
  chargeFailed, uttOrderId, fftOrderId,
  orderId: coins.orderId,
  amountOrderedK: coins.amountK,
  isSlow,
  giveUpHours: isSlow ? 72 : 48,
  startedAt: Date.now(),
  waitMinutes: chargeFailed ? 1 : (isSlow ? 10 : 3),
}}];

// ══════════════════════════════════════════════════════════════════
// COINS POLL EVALUATOR — supplier-aware (FFT/UTT), adaptive wait,
// FFT auto-resume, accountCheck → sallaFailKey (routed to the matching
// 'Salla Fail: *' node), staff-alert escalation. pollCount = $runIndex.
// ══════════════════════════════════════════════════════════════════
const prep = $('Coins: Prepare Poll').first().json;
const pollCount = ($runIndex || 0) + 1;
const raw = $input.first().json;
const ordered = prep.amountOrderedK;
const giveUpH = prep.giveUpHours || 48;
// Salla internal order id (owner confirmed the sallaFlow node expects data.id, 2026-07)
const sallaOrderId = (() => { try { return $('Webhook').first().json.body.data.id; } catch (e) { return null; } })();

if (prep.chargeFailed) {
  return [{ json: {
    shouldContinue: false, success: false, waitMinutes: 1, pollCount,
    deliveredK: 0, remaining: ordered, statusNorm: 'chargeFailed', credentialIssue: false,
    sallaFailKey: null, sallaOrderId,
    detail: 'no order id returned by supplier', supplier: prep.supplier,
    orderId: prep.orderId, elapsedHours: 0,
    alertMessage: `❌ طلب كوينز رقم ${prep.orderId} — المورد رفض طلب الشحن (لم يصدر رقم طلب)\n` +
      `يرجى فحص الطلب يدوياً`,
  }}];
}

let deliveredK = 0;
let statusNorm = 'unknown';   // finished | working | stalled | unknown
let detail = '';
let fftStatus = null;
let credentialIssue = false;
let acCredential = false;
let ac = '';
let ec = '';
let costEur = 0;

if (prep.supplier === 'UTT') {
  const o = raw.order || {};
  deliveredK = Math.round((o.amountProcessed || 0) / 1000);
  costEur = (parseFloat(o.moneySpent) || 0) + (parseFloat(o.privateMoneySpent) || 0);
  const s = String(o.statusOrder || '').toUpperCase();
  detail = s || 'no-response';
  if (deliveredK >= ordered && ordered > 0) statusNorm = 'finished';
  else if (s === 'COMPLETED') { statusNorm = 'stalled'; detail += ' (مكتمل لكن التسليم ناقص!)'; }
  else if (s.includes('NO AVAILABLE') || s.includes('STOP') || s.includes('ERROR') || s.includes('WRONG')) statusNorm = 'stalled';
  else if (s) statusNorm = 'working';
} else {
  let st = {};
  try { st = typeof raw.data === 'string' ? JSON.parse(raw.data) : (raw.data || raw); } catch (e) {}
  fftStatus = st;
  deliveredK = st.amount || 0;
  costEur = parseFloat(st.toPay) || 0;
  detail = `${st.status || 'no-response'} / ${st.economyState || '-'}`;
  if (st.status === 'finished' && deliveredK >= ordered) statusNorm = 'finished';
  else if (st.status === 'finished') { statusNorm = 'stalled'; detail += ' (منتهي لكن التسليم ناقص!)'; }
  else if (st.status === 'interrupted' || st.wasAborted === 1) statusNorm = 'stalled';
  else if (st.status) statusNorm = 'working';

  // FFT accountCheck codes that need the CUSTOMER/staff to act
  const BAD_CHECKS = ['wrongUserPass','wrongBA','noTM','noClub','wrongConsole','captcha','wrongPersona',
    'console','LoginFailedDeviceBan','tlFull','notEnoughCoins','unassignedItemsPresent','2FADisabled','No2FA','FailedPhone','TMLocked'];
  ac = String(st.accountCheck || '');
  if (statusNorm !== 'finished' && BAD_CHECKS.includes(ac)) {
    statusNorm = 'stalled';
    credentialIssue = true;
    acCredential = true;   // needs staff/customer to CORRECT data — resume alone won't help
    detail = `${st.status || '?'} / accountCheck: ${ac}`;
  }

  // economyState codes that ALSO mean the customer must act (web app locked/closed,
  // logged in on console, wrong data discovered mid-transfer, ...) — v14.7
  const BAD_ECONOMY = ['FailedWrongCredentialsTo','FailedWrongBACodeTo','FailLoggedInConsoleTo',
    'FailWebAppCustomerLocked','FailWebAppNotYetUnlocked','FailedReceiverDeviceBan','FailedTLfullReceiver','FailWebAppCustomerLocked?'];
  ec = String(st.economyState || '');
  if (statusNorm !== 'finished' && !credentialIssue && (BAD_ECONOMY.includes(ec) || ec.startsWith('FailedSessionExpired'))) {
    statusNorm = 'stalled';
    credentialIssue = true;   // resume CAN help once the customer fixes it (acCredential stays false)
    detail = `${st.status || '?'} / economyState: ${ec}`;
  }
}

// ── failure TYPE for the Salla status routing (Salla: Failure Type switch) ──
let sallaFailKey = null;
if (credentialIssue) {
  sallaFailKey =
      ['wrongUserPass','loginFailed','LoginFailed','LoginFailed401','LoginFailed495','LoginFailedDeviceBan','wrongPersona','2FADisabled','No2FA'].includes(ac) ? 'wrongEmailPass'
    : ac === 'wrongBA' ? 'wrongCodes'
    : ac === 'console' ? 'loggedIn'
    : ac === 'wrongConsole' ? 'wrongPlatform'
    : (ac === 'noTM' || ac === 'TMLocked') ? 'marketLocked'
    : ac === 'notEnoughCoins' ? 'noCoins'
    : ec === 'FailedWrongCredentialsTo' ? 'wrongEmailPass'
    : ec === 'FailedWrongBACodeTo' ? 'wrongCodes'
    : (ec === 'FailLoggedInConsoleTo' || ec.startsWith('FailedSessionExpired')) ? 'loggedIn'
    : (ec === 'FailWebAppCustomerLocked' || ec === 'FailWebAppNotYetUnlocked' || ec === 'FailWebAppCustomerLocked?') ? 'marketLocked'
    : null;
}

// ── FFT auto-resume: interrupted → resumeOrderAPI (polls 1,4,7; not for credential issues) ──
if (prep.supplier === 'FFT' && statusNorm === 'stalled' && !acCredential && prep.fftOrderId
    && fftStatus && fftStatus.status === 'interrupted'
    && ((pollCount % 3 === 1 && pollCount <= 9) || pollCount % 12 === 0)) {
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://futtransfer.top/resumeOrderAPI',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ apiUser: 'arabut11@gmail.com', apiKey: '8fb2834228a64f50858132de133fa75e', orderID: prep.fftOrderId, mode: 'resume' }),
    });
    detail += ' → auto-resume sent';
  } catch (e) { detail += ' → auto-resume failed'; }
}

// ── Adaptive wait ──
const remaining = Math.max(0, ordered - deliveredK);
let waitMinutes =
    remaining <= 300 ? 1
  : remaining <= 1000 ? 2
  : remaining <= 3000 ? 3
  : remaining <= 8000 ? 5
  : 8;
if (prep.isSlow) waitMinutes = Math.max(waitMinutes, 10);
if (statusNorm === 'stalled' || statusNorm === 'unknown') waitMinutes = 10;

// ── Escalation ──
const elapsedH = (Date.now() - (prep.startedAt || Date.now())) / 3600000;
const giveUp = elapsedH >= giveUpH;

let alertMessage = null;
// 🔑 credential/customer-data issues send NO ops alert (owner, 2026-07-06): Salla is
// updated + the customer is auto-notified with fix steps and the resume button; the
// ❌ 48h give-up alert below is the backstop. Stalled alerts = supplier-side only.
const stalledAlert = !credentialIssue && statusNorm === 'stalled' && (pollCount === 1 || pollCount % 12 === 0);
const unknownAlert = statusNorm === 'unknown' && (pollCount === 3 || pollCount % 12 === 0);
if (stalledAlert || unknownAlert) {
  alertMessage = `⚠️ طلب كوينز رقم ${prep.orderId} — الشحن متوقف\n` +
    `المورد: ${prep.supplier} | الحالة: ${detail}\n` +
    `تم التسليم: ${deliveredK}K من ${ordered}K\n` +
    `النظام يتابع تلقائياً (فحص رقم ${pollCount}) — تدخلوا فقط لو استمرت المشكلة`;
}
if (giveUp) {
  alertMessage = `❌ طلب كوينز رقم ${prep.orderId} — توقفت المتابعة بعد ${giveUpH} ساعة\n` +
    `المورد: ${prep.supplier} | الحالة: ${detail}\n` +
    `تم التسليم: ${deliveredK}K من ${ordered}K\n` +
    `يرجى المتابعة يدوياً`;
}

const success = statusNorm === 'finished';
// actual money spent (EUR from supplier) → USD with the live sheet rate
let actualCostEur = null, actualCostUsd = null;
if (success && costEur > 0) {
  const rate = (() => { try { return $('Router Logic1').first().json.usdToEurRate || 0.86; } catch (e) { return 0.86; } })();
  actualCostEur = Math.round(costEur * 100) / 100;
  actualCostUsd = Math.round((costEur / rate) * 100) / 100;
}
return [{ json: {
  shouldContinue: !success && !giveUp,
  success,
  waitMinutes,
  pollCount,
  deliveredK,
  remaining,
  statusNorm,
  credentialIssue,
  sallaFailKey,
  sallaOrderId,
  detail,
  supplier: prep.supplier,
  orderId: prep.orderId,
  actualCostEur,
  actualCostUsd,
  elapsedHours: Math.round(elapsedH * 10) / 10,
  alertMessage,
}}];

// Runs ONCE after the solves are accepted. Collects all sbcSolveIDs to track.
const solveIds = [];
for (const item of $input.all()) {
  try {
    const d = typeof item.json.data === 'string' ? JSON.parse(item.json.data) : (item.json.data || item.json);
    const arr = Array.isArray(d) ? d : [d];
    for (const s of arr) if (s && s.sbcSolveID) solveIds.push(s.sbcSolveID);
  } catch (e) {}
}
const matched = $('SBC: Match & Validate').first().json;
const expectedSolves = (() => { try { return (matched.sbcSetIDs || []).length; } catch (e) { return null; } })();
return [{ json: {
  solveIds,
  expectedSolves,
  missingSolves: expectedSolves != null && solveIds.length < expectedSolves,
  orderId: matched.orderId,
  sbcName: matched.sbcName,
  sallaOrderId: (() => { try { return $('Webhook').first().json.body.data.id; } catch (e) { return null; } })(),
  startedAt: Date.now(),
  waitMinutes: 5,
}}];

// ══════════════════════════════════════════════════════════════════
// SBC SOLVE EVALUATOR — tracks every sbcSolveID until ALL are finished.
// - transient technical failures  → auto-retry via retrySBCAPI (polls 2,6,10,14)
// - customer/funds failures       → staff alert + Salla failure status
// - all finished                  → success → Salla orderDone
// pollCount = $runIndex (stateless).
// ══════════════════════════════════════════════════════════════════
const prep = $('SBC Solve: Prepare Poll').first().json;
const pollCount = ($runIndex || 0) + 1;
const raw = $input.first().json;
let statuses = {};
try { statuses = typeof raw.data === 'string' ? JSON.parse(raw.data) : (raw.data || raw); } catch (e) {}
const ids = prep.solveIds || [];

const DONE = ['finished', 'alreadyCompleted'];
const WORKING = ['entered', 'waitingForOtherSolve', 'started', 'fetchSBCInfo', 'fetchChallengeInfo', 'solvingChallenge'];
const TRANSIENT = ['sessionExpired','FailProxyConn','FailedProxyConnectionError','LoginError','LoginFailed','LoginFailed401',
  'LoginFailed495','loginFailed','loginLoop','clickFailed','submitFailed','playerBuyFailed','playerNotFound','playerNotMoved',
  'clubQueryFailed','squadCreateFailed','challengeDataMissing','noPriceFound','noSolutionFound'];
// everything else (WrongBA, WrongUserPass, consoleLoggedIn, noFunds, OutOfCoins, tooExpensive,
// tempban, foundationNotSolved, setNotFound, aborted, failed, ...) needs a human decision.

let doneCount = 0, workingCount = 0;
const transient = [], manual = [];
let challengesDone = 0, challengesTotal = 0;
const details = [];
for (const id of ids) {
  const s = statuses[id] || {};
  const st = String(s.sbcStatus || 'unknown');
  challengesDone += s.challengesDone || 0;
  challengesTotal += s.totalChallenges || 0;
  details.push(`${st} (${s.challengesDone || 0}/${s.totalChallenges || '؟'})`);
  if (DONE.includes(st)) doneCount++;
  else if (WORKING.includes(st) || st === 'unknown') workingCount++;
  else if (TRANSIENT.includes(st)) transient.push({ id, st });
  else manual.push({ id, st });
}

// ── auto-retry transient technical failures ──
if (transient.length && pollCount % 4 === 2 && pollCount <= 14) {
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://futtransfer.top/retrySBCAPI',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ apiUser: 'arabut11@gmail.com', apiKey: '8fb2834228a64f50858132de133fa75e',
        sbcSolveID: transient.map(t => t.id) }),
    });
    details.push('→ auto-retry sent');
  } catch (e) { details.push('→ auto-retry failed'); }
}

// ── failure TYPE for the Salla status routing (Salla: Failure Type switch) ──
let sallaFailKey = null;
for (const m of manual) {
  const key =
      m.st === 'WrongBA' ? 'wrongCodes'
    : (m.st === 'WrongUserPass' || m.st === 'LoginFailedDeviceBan' || m.st === '2FADisabled' || m.st === 'needEmailConfirm') ? 'wrongEmailPass'
    : m.st === 'consoleLoggedIn' ? 'loggedIn'
    : m.st === 'TMLocked' ? 'marketLocked'
    : (m.st === 'noFunds' || m.st === 'OutOfCoins' || m.st === 'tooExpensive') ? 'noCoins'
    : null;
  if (key) { sallaFailKey = key; break; }
}

const success = ids.length > 0 && doneCount === ids.length;
const stalled = manual.length > 0 || (transient.length > 0 && pollCount > 14);
const elapsedH = (Date.now() - (prep.startedAt || Date.now())) / 3600000;
const giveUp = elapsedH >= 48 || ids.length === 0;

let waitMinutes = 5;
if (challengesTotal > 0 && challengesDone / challengesTotal >= 0.8) waitMinutes = 2;
if (stalled) waitMinutes = 15;

let alertMessage = null;
if (stalled && pollCount % 4 === 1) {
  alertMessage = `⚠️ طلب SBC رقم ${prep.orderId} — مشكلة في حل التحدي\n` +
    `التحدي: ${prep.sbcName}\n` +
    `الحالات: ${details.join(' | ')}\n` +
    (manual.length ? `يحتاج تدخل يدوي (${manual.map(m => m.st).join(', ')}) — راجعوا FFT\n` : '') +
    (sallaFailKey ? `تم تحديث حالة الطلب في سلة تلقائياً\n` : '') +
    `النظام يتابع (فحص رقم ${pollCount})`;
}
if (giveUp && !success) {
  alertMessage = `❌ طلب SBC رقم ${prep.orderId} — توقفت متابعة حل التحدي` +
    (ids.length === 0 ? ' (لا توجد أرقام حلول للتتبع)' : ' بعد 48 ساعة') + `\n` +
    `التحدي: ${prep.sbcName}\n` +
    `الحالات: ${details.join(' | ') || '-'}\n` +
    `مكتمل: ${doneCount} من ${ids.length} — يرجى المتابعة يدوياً من FFT`;
}

// solves that were tracked all finished, but some SBCs were never submitted at all
// (submission failed earlier) -> order must NOT close; tell ops to finish manually (v14.15)
if (success && prep.missingSolves) {
  alertMessage = `⚠️ طلب SBC رقم ${prep.orderId} — اكتملت الحلول المرسلة لكن جزءاً من التحديات لم يُرسل أصلاً (فشل إرساله سابقاً)\n` +
    `التحدي: ${prep.sbcName}\n` +
    `الطلب لن يُغلق تلقائياً — أكملوا الحل الناقص يدوياً من FFT ثم حدّثوا حالة سلة يدوياً`;
}

return [{ json: {
  shouldContinue: !success && !giveUp,
  success,
  waitMinutes,
  pollCount,
  doneCount,
  totalSolves: ids.length,
  challengesDone,
  challengesTotal,
  sallaFailKey,
  // partial solve-submit must never flip Salla to done (owner rule: ALL solves finished)
  sallaOrderId: (success && prep.missingSolves) ? null : prep.sallaOrderId,
  orderId: prep.orderId,
  sbcName: prep.sbcName,
  elapsedHours: Math.round(elapsedH * 10) / 10,
  detail: details.join(' | '),
  alertMessage,
}}];

const data = $('SBC: Match & Validate').first().json;
return data.sbcSetIDs.map(sbc => ({
  json: {
    setID: sbc.setID,
    sbcName: sbc.sbcName,
    challengeAmount: sbc.challengeAmount,
    timesToSolve: sbc.timesToSolve,
    orderId: data.orderId,
    eaEmail: data.eaEmail,
    customerName: data.customerName
  }
}));

