parameters.jsCode:
// =======================================================
// ROUTER LOGIC1 — coin order routing + pricing (6-tier)
// Reads PriceSettings from Google Sheet (15 rows) with hardcoded fallback
// Preserves: sbcTimesMultiplier, startCoins, multi-item SBC+coins merging
// =======================================================
// 1. استقبال البيانات (Input Handling)
// =======================================================
const inputJson = $('Webhook').first()?.json;
const body = inputJson.body || inputJson;

if (body.event !== "order.created") {
  throw new Error("⛔ تم تجاهل الحدث: " + (body.event || "unknown"));
}
const data = body.data;
if (!data || !data.items) {
  throw new Error("❌ خطأ: لم يتم العثور على بيانات الطلب!");
}

// =======================================================
// 3. تنسيق التاريخ (Date Formatting)
// =======================================================
const rawDate = data.date?.date || "";
let finalDate = "";
if (rawDate) {
    const justDate = rawDate.split(" ")[0];
    const [year, month, day] = justDate.split("-");
    finalDate = `${day}/${month}/${year}`;
}

// =======================================================
// 4. بيانات مشتركة للطلب كله (Common Order Data)
// =======================================================
const finalOrderId = data.reference_id || data.id;
const fullName = data.customer?.full_name || "Unknown";
const totalPriceSAR = parseFloat(data.amounts?.total?.amount || 0);
const mobileCode = (data.customer?.mobile_code || "").replace('+', '');
const mobileNum = (data.customer?.mobile || "").toString();

function extractCodesFromText(text) {
  return text.split('\n').map(c => c.replace('\r', '').trim()).filter(c => c.length > 0);
}

// ── Load PriceSettings from Google Sheet (6-tier with hardcoded fallback) ──
const HARDCODED_PRICE_SETTINGS = {
    usdToEurRate: 0.86,
    PS: {
        slow_AnyQty: 9,
        fast_Tier1: 11, fast_Tier2: 11, fast_Tier3: 13,
        fast_Tier4: 15, fast_Tier5: 15, fast_Tier6: 17
    },
    PC: {
        slow_AnyQty: 10,
        fast_Tier1: 25, fast_Tier2: 25, fast_Tier3: 25,
        fast_Tier4: 25, fast_Tier5: 25, fast_Tier6: 25
    }
};

let PriceSettings = JSON.parse(JSON.stringify(HARDCODED_PRICE_SETTINGS));
let priceSettingsSource = 'fallback';
let priceSettingsAgeH = null;

try {
    const sheetRows = $('Read Price Settings').all();
    const m = {};
    let loadedKeys = 0;
    for (const row of sheetRows) {
        const k = row.json.parameter;
        const v = parseFloat(row.json.value);
        if (k && !isNaN(v)) { m[k] = v; loadedKeys++; }
    }
    if (m.usd_to_eur_rate)    PriceSettings.usdToEurRate = m.usd_to_eur_rate;
    if (m.ps_slow_anyqty_usd) PriceSettings.PS.slow_AnyQty = m.ps_slow_anyqty_usd;
    if (m.ps_fast_tier1_usd)  PriceSettings.PS.fast_Tier1 = m.ps_fast_tier1_usd;
    if (m.ps_fast_tier2_usd)  PriceSettings.PS.fast_Tier2 = m.ps_fast_tier2_usd;
    if (m.ps_fast_tier3_usd)  PriceSettings.PS.fast_Tier3 = m.ps_fast_tier3_usd;
    if (m.ps_fast_tier4_usd)  PriceSettings.PS.fast_Tier4 = m.ps_fast_tier4_usd;
    if (m.ps_fast_tier5_usd)  PriceSettings.PS.fast_Tier5 = m.ps_fast_tier5_usd;
    if (m.ps_fast_tier6_usd)  PriceSettings.PS.fast_Tier6 = m.ps_fast_tier6_usd;
    if (m.pc_slow_anyqty_usd) PriceSettings.PC.slow_AnyQty = m.pc_slow_anyqty_usd;
    if (m.pc_fast_tier1_usd)  PriceSettings.PC.fast_Tier1 = m.pc_fast_tier1_usd;
    if (m.pc_fast_tier2_usd)  PriceSettings.PC.fast_Tier2 = m.pc_fast_tier2_usd;
    if (m.pc_fast_tier3_usd)  PriceSettings.PC.fast_Tier3 = m.pc_fast_tier3_usd;
    if (m.pc_fast_tier4_usd)  PriceSettings.PC.fast_Tier4 = m.pc_fast_tier4_usd;
    if (m.pc_fast_tier5_usd)  PriceSettings.PC.fast_Tier5 = m.pc_fast_tier5_usd;
    if (m.pc_fast_tier6_usd)  PriceSettings.PC.fast_Tier6 = m.pc_fast_tier6_usd;
    if (loadedKeys > 0) priceSettingsSource = 'sheet';
    // Staleness guard: the Auto-Updater stamps updated_at hourly. If it stops,
    // the sheet still loads "successfully" while prices drift — detect that.
    try {
        const stamps = sheetRows.map(row => Date.parse(row.json.updated_at)).filter(t => !isNaN(t));
        if (loadedKeys > 0 && stamps.length) {
            priceSettingsAgeH = Math.round(((Date.now() - Math.min(...stamps)) / 3600000) * 10) / 10;
            if (priceSettingsAgeH > 3) priceSettingsSource = 'stale';
        }
    } catch (e) {}
} catch (e) {
    // Silent fallback — order must not break if sheet read fails
}

// ── Tier picker (6 buckets by qtyK) ──
function pickTierUsd(currentPrices, amount) {
    if (amount <= 1000)  return currentPrices.fast_Tier1;
    if (amount <= 2000)  return currentPrices.fast_Tier2;
    if (amount <= 5000)  return currentPrices.fast_Tier3;
    if (amount <= 10000) return currentPrices.fast_Tier4;
    if (amount <= 15000) return currentPrices.fast_Tier5;
    return currentPrices.fast_Tier6;
}

// =======================================================
// 5. معالجة كل منتج في الطلب (Loop Through All Items)
// =======================================================
const allItems = data.items || [];
const results = [];

for (const item of allItems) {
  const options = item.options || [];
  const sku = (item.sku || "").toUpperCase();
  const prodName = (item.name || "").toLowerCase();

  // ── تحديد نوع المنتج ──
  let itemType = 'other';
  let productType = 'other';
  if (sku.includes('COIN')) { itemType = 'coins'; productType = 'coins'; }
  else if (sku.includes('FUT')) { itemType = 'fut'; productType = 'service'; }
  else if (sku.includes('RIVALS')) { itemType = 'rivals'; productType = 'service'; }
  else if (sku.includes('SBC')) { itemType = 'sbc'; productType = 'sbc'; }

  let finalNote = "";
  if (productType !== "coins") finalNote = item.name || "";

  let eaEmail = "", eaPass = "";
  let eaCodes = [], psCodes = [];
  let amount = 0, specificCoinPrice = 0;
  let platform = "PS";
  let isSlowShipping = false;
  let topUpEnabled = 1;
  let rankTarget = "";
  let rankUrgency = "anytime";
  let sbcTimesMultiplier = 1;
  let serviceQuantity = item.quantity || 1;
  let startCoins = 0;

  for (const opt of options) {
    const name = opt.name;
    const val = opt.value;
    const valString = (typeof val === 'object' && val.name) ? val.name : String(val);

    // ── الايميل ──
    if (name.includes("ايميل") || name.includes("Email")) eaEmail = valString.trim();

    // ── الباسورد ──
    if (name.includes("باسورد") || name.includes("Pass") || name.includes("كلمة مرور")) eaPass = valString.trim();

    // ── الأكواد الاحتياطية ──
    if (name.includes("الكود الاحتياطي") || name.includes("الأكواد الاحتياطية") || name.includes("Backup") || name.includes("code")) {
      const isSony = name.includes("سوني") || name.includes("Sony");
      if (opt.type === "textarea" || valString.includes("\n") || valString.includes("\r")) {
        const extracted = extractCodesFromText(valString);
        if (isSony) psCodes = psCodes.concat(extracted);
        else eaCodes = eaCodes.concat(extracted);
      } else {
        if (isSony) psCodes.push(valString.trim());
        else eaCodes.push(valString.trim());
      }
    }

    // ── المنصة ──
    if (name.includes("المنصة") || name.includes("Platform")) {
      if (valString.includes("PC") || valString.includes("بي سي")) platform = "PC";
      else platform = "PS";
    }

    // ── الرانك / الديفيجن (فوت + رايفلز) ──
    if (name.includes("الرانك") || name.includes("Rank") || name.includes("ديفيجن") || name.includes("division")) {
      rankTarget = valString;
    }

    // ── مدة التنفيذ / الاستعجال (فوت) ──
    if (name.includes("مدة تنفيذ")) {
      if (valString.includes("مستعجل") || valString.includes("24")) rankUrgency = "urgent";
    }

    // ── نوع الشحن (كوينز فقط) ──
    if (name.includes("نوع الشحن") || name.includes("Shipping") || name.includes("Type") || name.includes("protection")) {
      if (valString.includes("عادي") || valString.includes("بطيء") || valString.includes("بطيئ") || valString.includes("Slow")) {
        isSlowShipping = true;
      }
    }

    // ── الكمية (كوينز) ──
    if (name.includes("الكمية") || name.includes("Amount")) {
      let cleanVal = valString.replace(/,/g, '');
      const lowerValString = valString.toLowerCase();
      const match = cleanVal.match(/(\d+(\.\d+)?)/);
      if (match) {
        let extractedAmount = parseFloat(match[0]);
        if (lowerValString.includes("مليون")) extractedAmount *= 1000;
        let calculatedAmount = Math.round(extractedAmount);
        if (calculatedAmount > 0) {
          amount = calculatedAmount;
          if (typeof val === 'object' && val.price) specificCoinPrice = parseFloat(val.price.amount);
        }
      }
    }

    // ── رصيد الكوينز الحالي (Start Coins) ──
    if (name.includes("رصيد") || name.includes("الرصيد") || name.includes("Balance") || name.includes("balance")) {
      let cleanVal = valString.replace(/,/g, '');
      const matchCoins = cleanVal.match(/(\d+(\.\d+)?)/);
      if (matchCoins) {
        let sc = parseFloat(matchCoins[0]);
        if (valString.includes("مليون")) sc *= 1000000;
        else if (valString.includes("ألف") || valString.includes("الف")) sc *= 1000;
        startCoins = Math.round(sc);
      }
    }

    // ── عدد مرات الحل (للتحديات القابلة للتكرار) ──
    if (name.includes("عدد المرات") || name.includes("مرات") || name.includes("Times") || name.includes("Repetitions")) {
      const matchTimes = valString.match(/(\d+)/);
      if (matchTimes) {
        const n = parseInt(matchTimes[1], 10);
        if (n > 0) sbcTimesMultiplier = n;
      }
    }
  }

  // تصحيح المنصة من اسم المنتج أو الـ SKU
  if (sku.includes("PC") || prodName.includes("pc") || prodName.includes("بي سي") || prodName.includes("computer")) platform = "PC";

  // محاولة استخراج الكمية من اسم المنتج (كوينز فقط)
  if (productType === "coins" && amount === 0) {
    const match = (item.name || "").match(/(\d+)/);
    if (match) amount = parseInt(match[0]);
    else productType = "other";
  }

  if (platform === "PC") psCodes = [];

  let transferMethod = "";
  if (productType === "coins") transferMethod = "targetedSnipe";

  // ── حسابات التسعير (6-tier) ──
  let maxPricePer100k_EUR = 0;
  if (productType === "coins" || productType === "sbc") {
      const currentPrices = (platform === "PC") ? PriceSettings.PC : PriceSettings.PS;
      let targetMillionPriceUSD;

      if (productType === "sbc") {
          targetMillionPriceUSD = currentPrices.fast_Tier2;
      } else if (isSlowShipping) {
          targetMillionPriceUSD = currentPrices.slow_AnyQty;
      } else {
          targetMillionPriceUSD = pickTierUsd(currentPrices, amount);
      }

      const targetMillionPriceEUR = targetMillionPriceUSD * PriceSettings.usdToEurRate;
      maxPricePer100k_EUR = Math.round((targetMillionPriceEUR / 10) * 100) / 100;
  }

  // ── SBC Set ID ──
  let sbcSetID = null;
  if (productType === 'sbc') {
    const skuMatch = sku.match(/SBC_(\d+)/i);
    if (skuMatch) sbcSetID = parseInt(skuMatch[1]);
    else { sbcSetID = null; productType = "other"; }
  }

  results.push({
    json: {
      itemIndex: results.length,
      orderId: finalOrderId,
      orderDate: finalDate,
      customerName: fullName,
      mobile: mobileCode + mobileNum,
      totalPrice: totalPriceSAR,
      productType,
      itemType,
      sku,
      platform,
      note: finalNote,
      eaEmail,
      eaPass,
      eaBackup1: eaCodes[0] || "",
      eaBackup2: eaCodes[1] || "",
      eaBackup3: eaCodes[2] || "",
      psBackup1: psCodes[0] || "",
      psBackup2: psCodes[1] || "",
      psBackup3: psCodes[2] || "",
      amountK: amount,
      calculatedMaxPrice: maxPricePer100k_EUR,
      transferMethod,
      topUpEnabled,
      isSlowShipping,
      startCoins: startCoins || 200000,
      rankTarget,
      rankUrgency,
      serviceQuantity,
      sbcSetID,
      sbcTimesToSolve: productType === 'sbc' ? ((serviceQuantity || 1) * sbcTimesMultiplier) : null,
      usdToEurRate: PriceSettings.usdToEurRate,
      priceSettingsSource,
      priceSettingsAgeH,
    }
  });
}

// =======================================================
// 6.5 دمج طلبات الكوينز + SBC (منع التعارض على الحساب)
// =======================================================
const coinsItems = results.filter(r => r.json.productType === 'coins');
const sbcItems = results.filter(r => r.json.productType === 'sbc');
if (coinsItems.length > 0 && sbcItems.length > 0) {
  const totalExtraCoinsK = coinsItems.reduce((sum, r) => sum + (r.json.amountK || 0), 0);
  for (const sbcItem of sbcItems) sbcItem.json.extraCoinsK = totalExtraCoinsK;
  return results.filter(r => r.json.productType !== 'coins');
}

// =======================================================
// 6. الإرجاع النهائي (Return All Items)
// =======================================================
return results;

