// =======================================================
// SBC: Match & Validate (Multi-SBC Support) — 6-tier pricing
// Reads PriceSettings from Google Sheet with hardcoded fallback
// =======================================================

// ── 1. إعادة بناء مصفوفة التحديات من كل عناصر الـ input ──
const allInputItems = $input.all();
let availableSBCs = null;

if (allInputItems.length > 1) {
  availableSBCs = allInputItems.map(item => item.json);
}
if (!availableSBCs && allInputItems.length === 1) {
  const firstJson = allInputItems[0].json;
  if (Array.isArray(firstJson)) availableSBCs = firstJson;
  else if (firstJson.data && Array.isArray(firstJson.data)) availableSBCs = firstJson.data;
  else if (firstJson.sbcs && Array.isArray(firstJson.sbcs)) availableSBCs = firstJson.sbcs;
}
if (!availableSBCs && allInputItems.length === 1) {
  const firstJson = allInputItems[0].json;
  if (firstJson.setID !== undefined) availableSBCs = [firstJson];
}
if (!availableSBCs || !Array.isArray(availableSBCs) || availableSBCs.length === 0) {
  throw new Error(`❌ فشل قراءة قائمة التحديات. عدد العناصر المستقبلة: ${allInputItems.length}`);
}

// ── 2. جلب كل عناصر SBC من Router Logic ──
const allRouterItems = $('Router Logic1').all().map(i => i.json);
const sbcRouterItems = allRouterItems.filter(r => r.productType === 'sbc' && r.sbcSetID);

if (sbcRouterItems.length === 0) {
  throw new Error('❌ لم يتم العثور على أي SBC في بيانات الطلب');
}

const firstRouter = sbcRouterItems[0];
const platform = firstRouter.platform || 'PS';

// ── 3. التحقق من كل SBC مطلوب ──
const sbcSetIDs = [];
let totalCoinsK = 0;
let totalChallengeAmount = 0;
const sbcNames = [];

for (const routerItem of sbcRouterItems) {
  const setID = routerItem.sbcSetID;
  const sbcMatch = availableSBCs.find(sbc => Number(sbc.setID) === Number(setID));
  if (!sbcMatch) throw new Error(`❌ التحدي غير موجود: setID ${setID}`);

  const coinPrice = platform === 'PC'
    ? parseFloat(sbcMatch.pcPrice)
    : parseFloat(sbcMatch.consolePrice);

  if (!coinPrice || coinPrice <= 0) {
    const rawPrice = platform === 'PC' ? sbcMatch.pcPrice : sbcMatch.consolePrice;
    throw new Error(`⛔ FFT ما مسعّر هذا التحدي حالياً (السعر المستلم: ${rawPrice}) — غالباً غير قابل للحل الآلي: "${sbcMatch.sbcName}" [منصة ${platform}]. الطلب يحتاج حل يدوي.`);
  }

  const coinsPerSolveK = Math.ceil(coinPrice / 1000);
  const timesToSolve = routerItem.sbcTimesToSolve || 1;

  totalCoinsK += coinsPerSolveK * timesToSolve;
  totalChallengeAmount += (sbcMatch.challengeAmount || 0) * timesToSolve;
  sbcNames.push(sbcMatch.sbcName);

  sbcSetIDs.push({
    setID: sbcMatch.setID,
    sbcName: sbcMatch.sbcName,
    challengeAmount: sbcMatch.challengeAmount,
    expiry: sbcMatch.expiry,
    coinsPerSolveK,
    timesToSolve
  });
}

// ── 4. إضافة الكوينز الإضافية (لو فيه طلب كوينز مدمج) ──
const extraCoinsK = firstRouter.extraCoinsK || 0;
const totalAmountK = totalCoinsK + extraCoinsK;

// ── 5. حساب السعر الأقصى لكل 100K (PriceSettings from sheet, 6-tier) ──
const HARDCODED_PRICE_SETTINGS = {
  usdToEurRate: 0.86,
  PS: { slow_AnyQty: 9,  fast_Tier1: 11, fast_Tier2: 11, fast_Tier3: 13, fast_Tier4: 15, fast_Tier5: 15, fast_Tier6: 17 },
  PC: { slow_AnyQty: 10, fast_Tier1: 25, fast_Tier2: 25, fast_Tier3: 25, fast_Tier4: 25, fast_Tier5: 25, fast_Tier6: 25 }
};

let PriceSettings = JSON.parse(JSON.stringify(HARDCODED_PRICE_SETTINGS));

try {
  const rows = $('Read Price Settings').all().map(i => i.json);
  const g = (k) => {
    const row = rows.find(r => r.parameter === k);
    return row && row.value != null ? parseFloat(row.value) : null;
  };
  if (g('usd_to_eur_rate') != null)    PriceSettings.usdToEurRate   = g('usd_to_eur_rate');
  if (g('ps_slow_anyqty_usd') != null) PriceSettings.PS.slow_AnyQty = g('ps_slow_anyqty_usd');
  if (g('ps_fast_tier1_usd') != null)  PriceSettings.PS.fast_Tier1  = g('ps_fast_tier1_usd');
  if (g('ps_fast_tier2_usd') != null)  PriceSettings.PS.fast_Tier2  = g('ps_fast_tier2_usd');
  if (g('ps_fast_tier3_usd') != null)  PriceSettings.PS.fast_Tier3  = g('ps_fast_tier3_usd');
  if (g('ps_fast_tier4_usd') != null)  PriceSettings.PS.fast_Tier4  = g('ps_fast_tier4_usd');
  if (g('ps_fast_tier5_usd') != null)  PriceSettings.PS.fast_Tier5  = g('ps_fast_tier5_usd');
  if (g('ps_fast_tier6_usd') != null)  PriceSettings.PS.fast_Tier6  = g('ps_fast_tier6_usd');
  if (g('pc_slow_anyqty_usd') != null) PriceSettings.PC.slow_AnyQty = g('pc_slow_anyqty_usd');
  if (g('pc_fast_tier1_usd') != null)  PriceSettings.PC.fast_Tier1  = g('pc_fast_tier1_usd');
  if (g('pc_fast_tier2_usd') != null)  PriceSettings.PC.fast_Tier2  = g('pc_fast_tier2_usd');
  if (g('pc_fast_tier3_usd') != null)  PriceSettings.PC.fast_Tier3  = g('pc_fast_tier3_usd');
  if (g('pc_fast_tier4_usd') != null)  PriceSettings.PC.fast_Tier4  = g('pc_fast_tier4_usd');
  if (g('pc_fast_tier5_usd') != null)  PriceSettings.PC.fast_Tier5  = g('pc_fast_tier5_usd');
  if (g('pc_fast_tier6_usd') != null)  PriceSettings.PC.fast_Tier6  = g('pc_fast_tier6_usd');
} catch (e) {
  // Silent fallback
}

// ── Tier picker (6 buckets) ──
function pickTierUsd(currentPrices, amount) {
  if (amount <= 1000)  return currentPrices.fast_Tier1;
  if (amount <= 2000)  return currentPrices.fast_Tier2;
  if (amount <= 5000)  return currentPrices.fast_Tier3;
  if (amount <= 10000) return currentPrices.fast_Tier4;
  if (amount <= 15000) return currentPrices.fast_Tier5;
  return currentPrices.fast_Tier6;
}

const currentPrices = (platform === 'PC') ? PriceSettings.PC : PriceSettings.PS;
// If there's extra coins merged, price by total tier; else default SBC to T2
const targetMillionPriceUSD = extraCoinsK > 0
  ? pickTierUsd(currentPrices, totalAmountK)
  : currentPrices.fast_Tier2;

const targetMillionPriceEUR = targetMillionPriceUSD * PriceSettings.usdToEurRate;
const maxPricePer100k_EUR = Math.round((targetMillionPriceEUR / 10) * 100) / 100;

// ── 6. إرجاع عنصر واحد مدمج ──
return [{
  json: {
    sbcSetIDs,
    sbcName: sbcNames.join(' + '),
    challengeAmount: totalChallengeAmount,
    amountK: totalAmountK,
    extraCoinsK,
    platform,
    calculatedMaxPrice: maxPricePer100k_EUR,
    orderId: firstRouter.orderId,
    customerName: firstRouter.customerName,
    eaEmail: firstRouter.eaEmail,
    eaPass: firstRouter.eaPass,
    eaBackup1: firstRouter.eaBackup1,
    eaBackup2: firstRouter.eaBackup2,
    eaBackup3: firstRouter.eaBackup3,
    totalSBCsFound: availableSBCs.length,
    usdToEurRate: PriceSettings.usdToEurRate,
    startCoins: firstRouter.startCoins || 200000
  }
}];

// ══════════════════════════════════════════════════════════════════
// SBC POLL EVALUATOR — supplier-aware (FFT/UTT), adaptive wait,
// FFT auto-resume, accountCheck → sallaFailKey (routed to the matching
// 'Salla Fail: *' node), staff-alert escalation. pollCount = $runIndex.
// ══════════════════════════════════════════════════════════════════
const prep = $('SBC: Prepare Poll').first().json;
const pollCount = ($runIndex || 0) + 1;
const raw = $input.first().json;
const ordered = prep.amountOrderedK;
const giveUpH = prep.giveUpHours || 48;
// Salla internal order id (owner confirmed the sallaFlow node expects data.id, 2026-07)
const sallaOrderId = (() => { try { return $('Webhook').first().json.body.data.id; } catch (e) { return null; } })();

if (prep.chargeFailed) {
  return [{ json: {
    shouldContinue: false, success: false, waitMinutes: 1, pollCount,
    deliveredK: 0, remaining: ordered, statusNorm: 'chargeFailed', credentialIssue: false,
    sallaFailKey: null, sallaOrderId,
    detail: 'no order id returned by supplier', supplier: prep.supplier,
    orderId: prep.orderId, elapsedHours: 0,
    alertMessage: `❌ طلب SBC رقم ${prep.orderId} — المورد رفض طلب الشحن (لم يصدر رقم طلب)\n` +
      `يرجى فحص الطلب يدوياً`,
  }}];
}

let deliveredK = 0;
let statusNorm = 'unknown';   // finished | working | stalled | unknown
let detail = '';
let fftStatus = null;
let credentialIssue = false;
let acCredential = false;
let ac = '';
let ec = '';
let costEur = 0;

if (prep.supplier === 'UTT') {
  const o = raw.order || {};
  deliveredK = Math.round((o.amountProcessed || 0) / 1000);
  costEur = (parseFloat(o.moneySpent) || 0) + (parseFloat(o.privateMoneySpent) || 0);
  const s = String(o.statusOrder || '').toUpperCase();
  detail = s || 'no-response';
  if (deliveredK >= ordered && ordered > 0) statusNorm = 'finished';
  else if (s === 'COMPLETED') { statusNorm = 'stalled'; detail += ' (مكتمل لكن التسليم ناقص!)'; }
  else if (s.includes('NO AVAILABLE') || s.includes('STOP') || s.includes('ERROR') || s.includes('WRONG')) statusNorm = 'stalled';
  else if (s) statusNorm = 'working';
} else {
  let st = {};
  try { st = typeof raw.data === 'string' ? JSON.parse(raw.data) : (raw.data || raw); } catch (e) {}
  fftStatus = st;
  deliveredK = st.amount || 0;
  costEur = parseFloat(st.toPay) || 0;
  detail = `${st.status || 'no-response'} / ${st.economyState || '-'}`;
  if (st.status === 'finished' && deliveredK >= ordered) statusNorm = 'finished';
  else if (st.status === 'finished') { statusNorm = 'stalled'; detail += ' (منتهي لكن التسليم ناقص!)'; }
  else if (st.status === 'interrupted' || st.wasAborted === 1) statusNorm = 'stalled';
  else if (st.status) statusNorm = 'working';

  // FFT accountCheck codes that need the CUSTOMER/staff to act
  const BAD_CHECKS = ['wrongUserPass','wrongBA','noTM','noClub','wrongConsole','captcha','wrongPersona',
    'console','LoginFailedDeviceBan','tlFull','notEnoughCoins','unassignedItemsPresent','2FADisabled','No2FA','FailedPhone','TMLocked'];
  ac = String(st.accountCheck || '');
  if (statusNorm !== 'finished' && BAD_CHECKS.includes(ac)) {
    statusNorm = 'stalled';
    credentialIssue = true;
    acCredential = true;   // needs staff/customer to CORRECT data — resume alone won't help
    detail = `${st.status || '?'} / accountCheck: ${ac}`;
  }

  // economyState codes that ALSO mean the customer must act (web app locked/closed,
  // logged in on console, wrong data discovered mid-transfer, ...) — v14.7
  const BAD_ECONOMY = ['FailedWrongCredentialsTo','FailedWrongBACodeTo','FailLoggedInConsoleTo',
    'FailWebAppCustomerLocked','FailWebAppNotYetUnlocked','FailedReceiverDeviceBan','FailedTLfullReceiver','FailWebAppCustomerLocked?'];
  ec = String(st.economyState || '');
  if (statusNorm !== 'finished' && !credentialIssue && (BAD_ECONOMY.includes(ec) || ec.startsWith('FailedSessionExpired'))) {
    statusNorm = 'stalled';
    credentialIssue = true;   // resume CAN help once the customer fixes it (acCredential stays false)
    detail = `${st.status || '?'} / economyState: ${ec}`;
  }
}

// ── failure TYPE for the Salla status routing (Salla: Failure Type switch) ──
let sallaFailKey = null;
if (credentialIssue) {
  sallaFailKey =
      ['wrongUserPass','loginFailed','LoginFailed','LoginFailed401','LoginFailed495','LoginFailedDeviceBan','wrongPersona','2FADisabled','No2FA'].includes(ac) ? 'wrongEmailPass'
    : ac === 'wrongBA' ? 'wrongCodes'
    : ac === 'console' ? 'loggedIn'
    : ac === 'wrongConsole' ? 'wrongPlatform'
    : (ac === 'noTM' || ac === 'TMLocked') ? 'marketLocked'
    : ac === 'notEnoughCoins' ? 'noCoins'
    : ec === 'FailedWrongCredentialsTo' ? 'wrongEmailPass'
    : ec === 'FailedWrongBACodeTo' ? 'wrongCodes'
    : (ec === 'FailLoggedInConsoleTo' || ec.startsWith('FailedSessionExpired')) ? 'loggedIn'
    : (ec === 'FailWebAppCustomerLocked' || ec === 'FailWebAppNotYetUnlocked' || ec === 'FailWebAppCustomerLocked?') ? 'marketLocked'
    : null;
}

// ── FFT auto-resume: interrupted → resumeOrderAPI (polls 1,4,7; not for credential issues) ──
if (prep.supplier === 'FFT' && statusNorm === 'stalled' && !acCredential && prep.fftOrderId
    && fftStatus && fftStatus.status === 'interrupted'
    && ((pollCount % 3 === 1 && pollCount <= 9) || pollCount % 12 === 0)) {
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://futtransfer.top/resumeOrderAPI',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ apiUser: 'arabut11@gmail.com', apiKey: '8fb2834228a64f50858132de133fa75e', orderID: prep.fftOrderId, mode: 'resume' }),
    });
    detail += ' → auto-resume sent';
  } catch (e) { detail += ' → auto-resume failed'; }
}

// ── Adaptive wait ──
const remaining = Math.max(0, ordered - deliveredK);
let waitMinutes =
    remaining <= 300 ? 1
  : remaining <= 1000 ? 2
  : remaining <= 3000 ? 3
  : remaining <= 8000 ? 5
  : 8;
if (prep.isSlow) waitMinutes = Math.max(waitMinutes, 10);
if (statusNorm === 'stalled' || statusNorm === 'unknown') waitMinutes = 10;

// ── Escalation ──
const elapsedH = (Date.now() - (prep.startedAt || Date.now())) / 3600000;
const giveUp = elapsedH >= giveUpH;

let alertMessage = null;
// 🔑 credential/customer-data issues send NO ops alert (owner, 2026-07-06): Salla is
// updated + the customer is auto-notified with fix steps and the resume button; the
// ❌ 48h give-up alert below is the backstop. Stalled alerts = supplier-side only.
const stalledAlert = !credentialIssue && statusNorm === 'stalled' && (pollCount === 1 || pollCount % 12 === 0);
const unknownAlert = statusNorm === 'unknown' && (pollCount === 3 || pollCount % 12 === 0);
if (stalledAlert || unknownAlert) {
  alertMessage = `⚠️ طلب SBC رقم ${prep.orderId} — الشحن متوقف\n` +
    `المورد: ${prep.supplier} | الحالة: ${detail}\n` +
    `تم التسليم: ${deliveredK}K من ${ordered}K\n` +
    `النظام يتابع تلقائياً (فحص رقم ${pollCount}) — تدخلوا فقط لو استمرت المشكلة`;
}
if (giveUp) {
  alertMessage = `❌ طلب SBC رقم ${prep.orderId} — توقفت المتابعة بعد ${giveUpH} ساعة\n` +
    `المورد: ${prep.supplier} | الحالة: ${detail}\n` +
    `تم التسليم: ${deliveredK}K من ${ordered}K\n` +
    `يرجى المتابعة يدوياً — لن يتم حل التحدي تلقائياً`;
}

const success = statusNorm === 'finished';
// actual money spent (EUR from supplier) → USD with the live sheet rate
let actualCostEur = null, actualCostUsd = null;
if (success && costEur > 0) {
  const rate = (() => { try { return $('Router Logic1').first().json.usdToEurRate || 0.86; } catch (e) { return 0.86; } })();
  actualCostEur = Math.round(costEur * 100) / 100;
  actualCostUsd = Math.round((costEur / rate) * 100) / 100;
}
return [{ json: {
  shouldContinue: !success && !giveUp,
  success,
  waitMinutes,
  pollCount,
  deliveredK,
  remaining,
  statusNorm,
  credentialIssue,
  sallaFailKey,
  sallaOrderId,
  detail,
  supplier: prep.supplier,
  orderId: prep.orderId,
  actualCostEur,
  actualCostUsd,
  elapsedHours: Math.round(elapsedH * 10) / 10,
  alertMessage,
}}];

